import * as T from './vendor/three.js';
export function createTraffic(scene,network,count=48){
 const nodes=new Map(),edges=[];const id=p=>p.node||p.x.toFixed(2)+','+p.y.toFixed(2);
 for(const r of network.roads){if(!['residential','unclassified','tertiary','secondary','primary','living_street'].includes(r.type)||r.tags.access==='private'||r.tags.motor_vehicle==='no')continue;for(let i=0;i<r.p.length-1;i++){const a=r.p[i],b=r.p[i+1],length=a.distanceTo(b);if(length<1)continue;const add=reverse=>{const from=reverse?b:a,to=reverse?a:b,e={r,i,reverse,from,to,length,fromId:id(from),toId:id(to)};edges.push(e);if(!nodes.has(e.fromId))nodes.set(e.fromId,[]);nodes.get(e.fromId).push(e)};if(r.tags.oneway!=='-1')add(false);if(r.tags.oneway!=='yes'&&r.tags.junction!=='roundabout')add(true)}}
 let seed=519;const random=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};const queenEdges=edges.filter(e=>e.r.name==='Queen Street'&&e.length>12);const initial=edges.filter(e=>Math.hypot(e.from.x,e.from.y)<900&&e.length>12),others=edges.filter(e=>e.length>15);const cars=Array.from({length:Math.min(count+10,edges.length)},(_,i)=>{let pool=(i<4||i>=count)&&queenEdges.length?queenEdges:i<14&&initial.length?initial:others;const edge=i===0&&queenEdges.length?queenEdges[0]:pool[Math.floor(random()*pool.length)];return{edge,distance:edge.length*(.1+random()*.8),parked:i>=count,speed:i>=count?0:6+random()*5,velocity:0,yaw:0,position:null,index:i}});
 const palette=['#c9d9df','#34667f','#a64a4a','#d8d5c5','#448276','#566471','#e0ded2','#436294'];
 const part=(geometry,material,n=cars.length)=>{const m=new T.InstancedMesh(geometry,material,n);m.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(m);return m};
 const body=part(new T.BoxGeometry(1.75,.65,4.15),new T.MeshLambertMaterial({color:'#ffffff'}));for(let i=0;i<cars.length;i++)body.setColorAt(i,new T.Color(palette[i%palette.length]));
 const cabin=part(new T.BoxGeometry(1.5,.58,2),new T.MeshLambertMaterial({color:'#263f51'})),wheels=part(new T.BoxGeometry(.2,.5,.58),new T.MeshLambertMaterial({color:'#19222a'}),cars.length*4);
 const frontMaterial=new T.MeshBasicMaterial({color:'#fff7ca',toneMapped:false}),rearMaterial=new T.MeshBasicMaterial({color:'#e65952',toneMapped:false});const front=part(new T.BoxGeometry(.4,.15,.08),frontMaterial,cars.length*2),rear=part(new T.BoxGeometry(.4,.15,.08),rearMaterial,cars.length*2);
 const shadow=part(new T.PlaneGeometry(2.1,4.7),new T.MeshBasicMaterial({color:'#071019',transparent:true,opacity:.2,depthWrite:false,side:T.DoubleSide}));
 const dummy=new T.Object3D(),base=new T.Matrix4(),local=new T.Matrix4(),rotation=new T.Quaternion();
 function position(car){const e=car.edge,t=Math.min(1,car.distance/e.length),dx=(e.to.x-e.from.x)/e.length,dz=(e.to.y-e.from.y)/e.length,lane=car.parked?e.r.width/2+.6:Math.min(e.r.width*.23,2.5),x=T.MathUtils.lerp(e.from.x,e.to.x,t)+dz*lane,z=T.MathUtils.lerp(e.from.y,e.to.y,t)-dx*lane,rt=e.reverse?1-t:t,y=network.height(e.r,e.i,rt,x,z);return{x,z,y,dx,dz}}
 function write(mesh,index,x,y,z,rx=0){dummy.position.set(x,y,z);dummy.rotation.set(rx,0,0);dummy.updateMatrix();local.multiplyMatrices(base,dummy.matrix);mesh.setMatrixAt(index,local)}
 function update(dt,camera,night=0){for(const car of cars){const current=position(car);let target=car.speed;const px=camera.x-current.x,pz=camera.z-current.z,forward=px*current.dx+pz*current.dz;if(forward>0&&forward<9&&Math.abs(px*current.dz-pz*current.dx)<2.2&&Math.abs(camera.y-current.y)<4)target=car.speed*Math.max(0,(forward-3)/6);for(const other of cars){if(other===car||!other.position)continue;let dx=other.position.x-current.x,dz=other.position.z-current.z,d=dx*current.dx+dz*current.dz;if(d>0&&d<10&&Math.abs(dx*current.dz-dz*current.dx)<1.6)target=Math.min(target,car.speed*Math.max(0,(d-4)/6))}car.velocity=T.MathUtils.lerp(car.velocity,target,Math.min(1,dt*2));car.distance+=car.velocity*dt;let safety=0;while(car.distance>=car.edge.length&&safety++<8){car.distance-=car.edge.length;const options=nodes.get(car.edge.toId)||[],forward=options.filter(e=>e.toId!==car.edge.fromId),choices=forward.length?forward:options;if(!choices.length){const reverse={...car.edge,from:car.edge.to,to:car.edge.from,fromId:car.edge.toId,toId:car.edge.fromId,reverse:!car.edge.reverse};car.edge=reverse}else car.edge=choices[Math.floor(random()*choices.length)]}const p=position(car),targetYaw=Math.atan2(-p.dx,-p.dz);if(!car.position){car.position={...p};car.yaw=targetYaw}else{car.position.x=T.MathUtils.lerp(car.position.x,p.x,Math.min(1,dt*9));car.position.z=T.MathUtils.lerp(car.position.z,p.z,Math.min(1,dt*9));car.position.y=p.y;const angle=Math.atan2(Math.sin(targetYaw-car.yaw),Math.cos(targetYaw-car.yaw));car.yaw+=angle*Math.min(1,dt*7)}const e=car.edge,tAhead=Math.min(1,car.distance/e.length+2/e.length),rt=e.reverse?1-tAhead:tAhead,ax=T.MathUtils.lerp(e.from.x,e.to.x,tAhead),az=T.MathUtils.lerp(e.from.y,e.to.y,tAhead),ay=network.height(e.r,e.i,rt,ax,az),pitch=Math.atan2(ay-p.y,Math.max(.1,(tAhead-car.distance/e.length)*e.length));rotation.setFromEuler(new T.Euler(pitch,car.yaw,0,'YXZ'));base.compose(new T.Vector3(car.position.x,car.position.y,car.position.z),rotation,new T.Vector3(1,1,1));write(body,car.index,0,.66,0);write(cabin,car.index,0,1.23,.25);for(let j=0;j<4;j++)write(wheels,car.index*4+j,j%2?-.91:.91,.35,j<2?-1.27:1.27);for(let j=0;j<2;j++){write(front,car.index*2+j,j?-.55:.55,.76,-2.1);write(rear,car.index*2+j,j?-.55:.55,.76,2.1)}write(shadow,car.index,0,.035,0,-Math.PI/2)}frontMaterial.color.set('#d6dfde').lerp(new T.Color('#fff5bb'),night);for(const mesh of [body,cabin,wheels,front,rear,shadow])mesh.instanceMatrix.needsUpdate=true}
 update(0,new T.Vector3(0,1000,0));return{cars,edges,nodes,update};
}
